/**
 * Starting hands, strongest first. Generated by tools/gen-handrank.test.ts —
 * do not edit by hand.
 *
 * `equity` is the raw chance of beating one random hand all-in to the river,
 * measured over 30,000 deals. The ordering adds a small playability bonus for
 * suited and connected hands, because all-in equity alone undervalues hands
 * that win by making flushes and straights over several streets.
 *
 * `percentile` (below) is what the bots actually use: "this hand is in the
 * top N% of all starting hands".
 */

export interface RankedHand {
  name: string;
  /** Class index in the 13x13 grid used by engine/range.ts. */
  index: number;
  equity: number;
  rank: number;
}

