/** Combos in each class, before card removal: 6 pairs, 4 suited, 12 offsuit. */
function comboCount(name: string): number {
  if (name.length === 2) return 6;
  return name.endsWith('s') ? 4 : 12;
}

const TOTAL_COMBOS = 1326;

/**
 * Share of all starting hands at least as strong as this one, 0..1.
 * A hand with percentile 0.15 is in the top 15% of hands.
 */
export const HAND_PERCENTILE: Record<string, number> = (() => {
  const out: Record<string, number> = {};
  let seen = 0;
  for (const h of RANKED_HANDS) {
    seen += comboCount(h.name);
    out[h.name] = seen / TOTAL_COMBOS;
  }
  return out;
})();

export const PERCENTILE_BY_INDEX: number[] = (() => {
  const out = new Array(169).fill(1);
  for (const h of RANKED_HANDS) out[h.index] = HAND_PERCENTILE[h.name];
  return out;
})();
